<?php require_once __DIR__.'/database.php';class DoctorModel{private PDO $db;function __construct(){$this->db=Database::get();}function all($dept='',$name=''){ $q="SELECT d.*,u.name,u.email,u.phone,p.name department_name FROM doctors d JOIN users u ON u.id=d.user_id JOIN departments p ON p.id=d.department_id WHERE 1=1";$a=[];if($dept!==''){$q.=' AND d.department_id=?';$a[]=$dept;}if(trim($name)!==''){$q.=' AND u.name LIKE ?';$a[]='%'.trim($name).'%';}$q.=' ORDER BY u.name';$s=$this->db->prepare($q);$s->execute($a);return $s->fetchAll();}function find($id){$s=$this->db->prepare("SELECT d.*,u.name,u.email,u.phone,p.name department_name FROM doctors d JOIN users u ON u.id=d.user_id JOIN departments p ON p.id=d.department_id WHERE d.id=?");$s->execute([$id]);return $s->fetch()?:null;}function byUser($id){$s=$this->db->prepare('SELECT d.*,u.name,u.email,u.phone,p.name department_name FROM doctors d JOIN users u ON u.id=d.user_id JOIN departments p ON p.id=d.department_id WHERE d.user_id=?');$s->execute([$id]);return $s->fetch()?:null;}function save($x){$db=$this->db;$db->beginTransaction();try{if($x['doctor_id']){$s=$db->prepare('UPDATE users SET name=?,email=?,phone=? WHERE id=?');$s->execute([$x['name'],$x['email'],$x['phone'],$x['user_id']]);$s=$db->prepare('UPDATE doctors SET department_id=?,specialization=?,fee=?,available_days=?,start_time=?,end_time=?,room=? WHERE id=?');$s->execute([$x['department_id'],$x['specialization'],$x['fee'],$x['available_days'],$x['start_time'],$x['end_time'],$x['room'],$x['doctor_id']]);}else{$s=$db->prepare("INSERT INTO users(name,email,phone,password,role) VALUES(?,?,?,?, 'doctor')");$s->execute([$x['name'],$x['email'],$x['phone'],password_hash($x['password'],PASSWORD_DEFAULT)]);$uid=$db->lastInsertId();$s=$db->prepare('INSERT INTO doctors(user_id,department_id,specialization,fee,available_days,start_time,end_time,room) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$uid,$x['department_id'],$x['specialization'],$x['fee'],$x['available_days'],$x['start_time'],$x['end_time'],$x['room']]);}$db->commit();return true;}catch(Throwable $e){$db->rollBack();throw $e;}}function delete($id){$s=$this->db->prepare('SELECT user_id FROM doctors WHERE id=?');$s->execute([$id]);$u=$s->fetch();if(!$u)return false;$this->db->prepare('DELETE FROM doctors WHERE id=?')->execute([$id]);$this->db->prepare('DELETE FROM users WHERE id=?')->execute([$u['user_id']]);return true;}}
?>